/* ------------------------------------------------------------------ */
/*  Looping "instant deploy" terminal                                  */
/* ------------------------------------------------------------------ */

const COMMAND = "nxeon deploy --plan pro --os ubuntu";

type OutLine = { text: string; tone: "muted" | "ok" | "info" | "accent" };

const OUTPUT: OutLine[] = [
  { text: "→ Allocating NVMe volume on ZFS mirror…", tone: "muted" },
  { text: "→ Cloning Ubuntu 24.04 template (cloud-init)…", tone: "muted" },
  { text: "→ Attaching dedicated IPv4 · configuring firewall…", tone: "muted" },
  { text: "✓ Server web-prod-01 is live in 47s", tone: "ok" },
  { text: "  ssh root@51.79.162.96 -p 20114", tone: "accent" },
];

function DeployTerminal() {
  const [typed, setTyped] = useState("");
  const [lines, setLines] = useState<OutLine[]>([]);
  const [phase, setPhase] = useState<"typing" | "running" | "done">("typing");
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  useEffect(() => {
    let cancelled = false;
    const wait = (ms: number) =>
      new Promise<void>((res) => {
        const t = setTimeout(res, ms);
        timers.current.push(t);
      });

    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;

    async function loop() {
      while (!cancelled) {
        // reset
        setTyped("");
        setLines([]);
        setPhase("typing");
        await wait(600);

        if (reduce) {
          setTyped(COMMAND);
          setLines(OUTPUT);
          setPhase("done");
          await wait(6000);
          continue;
        }

        // type the command
        for (let i = 1; i <= COMMAND.length; i++) {
          if (cancelled) return;
          setTyped(COMMAND.slice(0, i));
          await wait(38 + (COMMAND[i - 1] === " " ? 40 : 0));
        }
        await wait(400);
        setPhase("running");

        // stream output
        for (const line of OUTPUT) {
          if (cancelled) return;
          setLines((prev) => [...prev, line]);
          await wait(line.tone === "ok" ? 720 : 620);
        }
        setPhase("done");
        await wait(3400);
      }
    }
    loop();

    return () => {
      cancelled = true;
      timers.current.forEach(clearTimeout);
      timers.current = [];
    };
  }, []);

  const toneClass: Record<OutLine["tone"], string> = {
    muted: "text-slate-400",
    ok: "text-emerald-300 font-medium",
    info: "text-brand-300",
    accent: "text-accent-cyan",
  };

  return (
    <div className="nx-terminal glass relative overflow-hidden shadow-2xl">
      <div className="pointer-events-none absolute -inset-8 rounded-[2.5rem] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 blur-2xl" />
      <div className="relative">
        {/* window chrome */}
        <div className="flex items-center gap-2 border-b border-white/[0.06] px-4 py-3">
          <span className="h-3 w-3 rounded-full bg-red-400/70" />
          <span className="h-3 w-3 rounded-full bg-amber-400/70" />
          <span className="h-3 w-3 rounded-full bg-emerald-400/70" />
          <span className="ml-3 flex items-center gap-2 rounded-md border border-white/10 bg-white/[0.04] px-3 py-1 text-[11px] text-slate-500">
            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse-dot" />
            nxeon@cloud — deploy
          </span>
        </div>

        <div className="min-h-[248px] px-4 py-4 font-mono text-[12.5px] leading-relaxed sm:text-[13px]">
          <div className="flex flex-wrap items-baseline gap-x-2">
            <span className="text-emerald-400">$</span>
            <span className="break-all text-slate-100">
              {typed}
              {phase === "typing" && <span className="nx-caret">▋</span>}
            </span>
          </div>

          <div className="mt-3 space-y-1.5">
            {lines.map((l, i) => (
              <div key={i} className={`nx-line ${toneClass[l.tone]}`}>
                {l.text}
              </div>
            ))}
          </div>

          {phase === "done" && (
            <div className="nx-line mt-4 inline-flex items-center gap-2 rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-2.5 py-1 text-[11px] font-medium text-emerald-300">
              <span className="flex h-3.5 w-3.5 items-center justify-center">
                <IconCheck size={11} />
              </span>
              Deployment complete
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

