"use client";

import Link from "next/link";
import { useEffect, useRef, useState } from "react";
import { IconArrow, IconCheck } from "./icons";

type Result = {
  domain: string;
  available: boolean;
  premium: boolean;
  priceCents: number | null;
  renewCents: number | null;
};

type Status = "idle" | "loading" | "results" | "soon" | "auth" | "error";

/** Curated popular TLDs with indicative starting prices (USD/yr). Static — live
 *  per-domain pricing comes from a search. Clearly labelled as "from". */
export const POPULAR_TLDS: { tld: string; fromCents: number }[] = [
  { tld: ".com", fromCents: 1099 },
  { tld: ".net", fromCents: 1299 },
  { tld: ".io", fromCents: 3499 },
  { tld: ".dev", fromCents: 1499 },
  { tld: ".app", fromCents: 1599 },
  { tld: ".xyz", fromCents: 299 },
  { tld: ".co", fromCents: 2499 },
  { tld: ".ai", fromCents: 6999 },
];

function money(cents: number | null): string {
  if (cents == null) return "—";
  const v = cents / 100;
  return `$${v.toFixed(2)}`;
}

export function DomainChecker({ compact = false }: { compact?: boolean }) {
  const [q, setQ] = useState("");
  const [status, setStatus] = useState<Status>("idle");
  const [results, setResults] = useState<Result[]>([]);
  const debounce = useRef<ReturnType<typeof setTimeout> | null>(null);
  const abort = useRef<AbortController | null>(null);

  useEffect(() => {
    const query = q.trim().toLowerCase();
    if (debounce.current) clearTimeout(debounce.current);
    abort.current?.abort();

    if (query.length < 2) {
      setStatus("idle");
      setResults([]);
      return;
    }

    setStatus("loading");
    debounce.current = setTimeout(async () => {
      const ac = new AbortController();
      abort.current = ac;
      try {
        const res = await fetch(`/api/domains/check?q=${encodeURIComponent(query)}`, {
          signal: ac.signal,
        });
        if (res.status === 401) {
          setStatus("auth");
          return;
        }
        const data = await res.json();
        if (data.configured === false) {
          setStatus("soon");
          return;
        }
        const list: Result[] = Array.isArray(data.results) ? data.results : [];
        setResults(list);
        setStatus("results");
      } catch (e: any) {
        if (e?.name === "AbortError") return;
        setStatus("error");
      }
    }, 400);

    return () => {
      if (debounce.current) clearTimeout(debounce.current);
    };
  }, [q]);

  const sorted = [...results].sort(
    (a, b) => Number(b.available) - Number(a.available) || (a.priceCents ?? 0) - (b.priceCents ?? 0),
  );

  return (
    <div className="w-full">
      <style>{`
        .nx-dom-row { animation: nx-dom-in 0.35s cubic-bezier(0.22,1,0.36,1) both; }
        @keyframes nx-dom-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
        .nx-dot { animation: nx-dot 1s ease-in-out infinite; }
        .nx-dot:nth-child(2) { animation-delay: 0.15s; }
        .nx-dot:nth-child(3) { animation-delay: 0.3s; }
        @keyframes nx-dot { 0%,100% { opacity: 0.25; } 50% { opacity: 1; } }
        @media (prefers-reduced-motion: reduce) { .nx-dom-row, .nx-dot { animation: none !important; } }
      `}</style>

      {/* Search field */}
      <div className="group relative">
        <div className="pointer-events-none absolute -inset-[1px] rounded-2xl bg-gradient-to-r from-accent-blue/40 via-brand-500/40 to-accent-cyan/40 opacity-0 blur transition-opacity duration-300 group-focus-within:opacity-100" />
        <div className="relative flex items-center gap-2 rounded-2xl border border-white/10 bg-navy-900/80 p-2 backdrop-blur-md transition-colors focus-within:border-brand-400/50">
          <span className="pl-2 text-slate-500" aria-hidden>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="11" cy="11" r="7" />
              <path d="m20 20-3-3" />
            </svg>
          </span>
          <input
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Find your perfect domain…"
            spellCheck={false}
            autoCapitalize="off"
            autoCorrect="off"
            className="min-w-0 flex-1 bg-transparent px-1 py-2.5 text-base text-slate-100 outline-none placeholder:text-slate-500"
            aria-label="Search for a domain"
          />
          <span className="hidden shrink-0 items-center gap-2 pr-2 text-xs text-slate-500 sm:flex">
            {status === "loading" ? (
              <>
                <span className="nx-dot h-1.5 w-1.5 rounded-full bg-brand-400" />
                <span className="nx-dot h-1.5 w-1.5 rounded-full bg-brand-400" />
                <span className="nx-dot h-1.5 w-1.5 rounded-full bg-brand-400" />
              </>
            ) : (
              <span className="rounded-md border border-white/10 bg-white/[0.04] px-2 py-1">
                Try nxeon
              </span>
            )}
          </span>
        </div>
      </div>

      {/* Results / states */}
      <div className="mt-4">
        {status === "results" && sorted.length > 0 && (
          <ul className="space-y-2">
            {sorted.map((r, i) => (
              <li
                key={r.domain}
                className="nx-dom-row flex flex-wrap items-center gap-3 rounded-xl border border-white/[0.07] bg-navy-900/60 px-4 py-3 backdrop-blur-md transition-colors hover:border-brand-500/30"
                style={{ animationDelay: `${i * 45}ms` }}
              >
                <span
                  className={`flex h-7 w-7 items-center justify-center rounded-full ${
                    r.available ? "bg-emerald-500/15 text-emerald-400" : "bg-slate-500/15 text-slate-500"
                  }`}
                >
                  {r.available ? (
                    <IconCheck size={14} />
                  ) : (
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                      <path d="M6 6l12 12M18 6 6 18" />
                    </svg>
                  )}
                </span>
                <span className="font-mono text-sm font-medium text-white">{r.domain}</span>
                {r.premium && (
                  <span className="rounded-full border border-amber-400/30 bg-amber-400/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-amber-300">
                    Premium
                  </span>
                )}
                <span className="ml-auto flex items-center gap-3">
                  {r.available ? (
                    <>
                      <span className="text-right text-sm">
                        <span className="font-semibold text-white">{money(r.priceCents)}</span>
                        <span className="text-slate-500">/yr</span>
                      </span>
                      <Link
                        href={`/register?domain=${encodeURIComponent(r.domain)}`}
                        className="btn-primary px-3.5 py-1.5 text-xs"
                      >
                        Register
                        <IconArrow size={13} />
                      </Link>
                    </>
                  ) : (
                    <span className="text-xs text-slate-500">Taken</span>
                  )}
                </span>
              </li>
            ))}
          </ul>
        )}

        {status === "results" && sorted.length === 0 && (
          <p className="rounded-xl border border-white/[0.07] bg-navy-900/60 px-4 py-3 text-sm text-slate-400">
            No matches for that query — try a different name.
          </p>
        )}

        {status === "auth" && (
          <div className="rounded-xl border border-brand-500/25 bg-brand-500/[0.06] px-4 py-3 text-sm text-slate-300">
            <b className="text-white">Live availability is one step away.</b>{" "}
            <Link href="/register" className="text-brand-300 hover:underline">
              Create a free account
            </Link>{" "}
            to search and register domains in real time — then point them at your VPS in a click.
          </div>
        )}

        {status === "soon" && (
          <div className="rounded-xl border border-amber-400/25 bg-amber-400/[0.06] px-4 py-3 text-sm text-amber-200/90">
            <b>Domain registration is launching soon.</b> Prices below are indicative starting
            rates — check back shortly to register live.
          </div>
        )}

        {status === "error" && (
          <p className="rounded-xl border border-red-500/25 bg-red-500/[0.06] px-4 py-3 text-sm text-red-300">
            Something went wrong checking that domain. Please try again.
          </p>
        )}
      </div>

      {/* Popular TLD chips */}
      {!compact && (
        <div className="mt-6">
          <p className="mb-3 text-xs font-medium uppercase tracking-wider text-slate-500">
            Popular extensions · from
          </p>
          <div className="flex flex-wrap gap-2">
            {POPULAR_TLDS.map((t) => (
              <span
                key={t.tld}
                className="inline-flex items-center gap-2 rounded-lg border border-white/[0.08] bg-white/[0.03] px-3 py-1.5 text-sm text-slate-300 transition-colors hover:border-brand-500/30 hover:text-white"
              >
                <span className="font-mono font-semibold text-brand-300">{t.tld}</span>
                <span className="text-xs text-slate-500">{money(t.fromCents)}</span>
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Animated "global reach" motif — a stylised network globe with pulsing edge
 * nodes and travelling data arcs. Pure SVG + scoped CSS keyframes, no assets.
 * Server-safe (renders a <style> tag with static markup).
 */
export function GlobalNetwork() {
  const nodes = [
    { cx: 90, cy: 120, d: "0s" },
    { cx: 250, cy: 70, d: "0.6s" },
    { cx: 420, cy: 110, d: "1.2s" },
    { cx: 150, cy: 250, d: "0.9s" },
    { cx: 330, cy: 260, d: "0.3s" },
    { cx: 470, cy: 230, d: "1.5s" },
  ];
  const arcs = [
    "M90 120 Q180 20 250 70",
    "M250 70 Q360 30 420 110",
    "M90 120 Q120 200 150 250",
    "M150 250 Q240 300 330 260",
    "M330 260 Q420 300 470 230",
    "M250 70 Q300 170 330 260",
  ];

  return (
    <div className="relative mx-auto w-full max-w-xl">
      <div className="pointer-events-none absolute inset-0 rounded-full bg-gradient-to-br from-accent-blue/15 to-brand-500/15 blur-3xl" />
      <svg viewBox="0 0 540 340" className="relative w-full" role="img" aria-label="Global network reach">
        <defs>
          <radialGradient id="ng-globe" cx="50%" cy="40%" r="65%">
            <stop offset="0%" stopColor="#1a2540" stopOpacity="0.9" />
            <stop offset="100%" stopColor="#060a14" stopOpacity="0.2" />
          </radialGradient>
          <linearGradient id="ng-arc" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor="#3b82f6" />
            <stop offset="100%" stopColor="#8a70fb" />
          </linearGradient>
        </defs>

        {/* globe body */}
        <circle cx="270" cy="170" r="150" fill="url(#ng-globe)" stroke="rgba(255,255,255,0.06)" />
        {/* longitude / latitude lines */}
        <g stroke="rgba(138,112,251,0.22)" fill="none" strokeWidth="1">
          <ellipse cx="270" cy="170" rx="150" ry="60" />
          <ellipse cx="270" cy="170" rx="150" ry="110" />
          <ellipse cx="270" cy="170" rx="60" ry="150" />
          <ellipse cx="270" cy="170" rx="110" ry="150" />
          <line x1="120" y1="170" x2="420" y2="170" />
          <line x1="270" y1="20" x2="270" y2="320" />
        </g>

        {/* travelling arcs */}
        <g fill="none" stroke="url(#ng-arc)" strokeWidth="1.6" strokeLinecap="round">
          {arcs.map((d, i) => (
            <path
              key={i}
              d={d}
              className="ng-arc"
              style={{ animationDelay: `${i * 0.5}s` }}
              strokeDasharray="6 210"
            />
          ))}
        </g>

        {/* nodes */}
        {nodes.map((n, i) => (
          <g key={i}>
            <circle cx={n.cx} cy={n.cy} r="10" className="ng-ring" style={{ animationDelay: n.d }} fill="none" stroke="#8a70fb" strokeWidth="1.4" />
            <circle cx={n.cx} cy={n.cy} r="3.5" fill="#a89aff" />
          </g>
        ))}
      </svg>

      <style>{`
        .ng-arc {
          animation: ng-travel 3.4s ease-in-out infinite;
          opacity: 0.9;
        }
        @keyframes ng-travel {
          0% { stroke-dashoffset: 216; opacity: 0; }
          20% { opacity: 1; }
          80% { opacity: 1; }
          100% { stroke-dashoffset: 0; opacity: 0; }
        }
        .ng-ring {
          transform-box: fill-box;
          transform-origin: center;
          animation: ng-pulse 2.6s ease-out infinite;
        }
        @keyframes ng-pulse {
          0% { transform: scale(0.5); opacity: 0.9; }
          70% { transform: scale(1.9); opacity: 0; }
          100% { transform: scale(1.9); opacity: 0; }
        }
        @media (prefers-reduced-motion: reduce) {
          .ng-arc, .ng-ring { animation: none !important; }
          .ng-arc { opacity: 0.7; stroke-dasharray: none; }
        }
      `}</style>
    </div>
  );
}

