input.content:
import Link from "next/link";
import type { Metadata } from "next";
import { db } from "@/lib/db";
import { Reveal } from "@/components/marketing/Reveal";
import { PricingGrid } from "@/components/marketing/PricingGrid";
import { DeployCatalog, type CatalogGroup } from "@/components/marketing/DeployCatalog";
import { StatCounter } from "@/components/marketing/StatCounter";
import { SectionHeading, FeatureCard, CtaBand } from "@/components/marketing/sections";
import {
  IconNvme,
  IconTerminal,
  IconBackup,
  IconShield,
  IconApps,
  IconServer,
  IconGauge,
  IconScale,
  IconGlobe,
  IconArrow,
  IconCheck,
} from "@/components/marketing/icons";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "VPS Hosting — Nxeon",
  description:
    "High-performance NVMe cloud VPS with full root access, snapshots, backups, DDoS protection, and one-click apps. Deploy in seconds.",
};

const CATEGORY_LABELS: Record<string, string> = {
  PLAIN_OS: "Operating systems",
  CONTROL_PANEL: "Control panels",
  APPLICATION: "One-click apps",
};

const FALLBACK: Record<string, string[]> = {
  PLAIN_OS: ["Ubuntu 24.04", "Debian 13", "AlmaLinux 9", "Rocky Linux 9", "Fedora"],
  CONTROL_PANEL: ["cPanel", "Plesk", "CyberPanel", "Webmin", "CloudPanel", "aaPanel", "HestiaCP"],
  APPLICATION: ["Docker", "WordPress", "Nextcloud", "Ghost", "n8n", "PostgreSQL"],
};

const INCLUDED = [
  { icon: <IconTerminal />, title: "Full root access", body: "Complete control over your server via SSH. Install anything, tune the kernel, run containers — it is your box, not a sandbox." },
  { icon: <IconNvme />, title: "Enterprise NVMe", body: "Every plan runs on NVMe SSD in a ZFS mirror for real IOPS — fast boots, fast builds, fast databases." },
  { icon: <IconServer />, title: "Snapshots", body: "Capture a point-in-time image before a risky change and roll back instantly if it goes sideways." },
  { icon: <IconBackup />, title: "Automatic backups", body: "Scheduled snapshots stream to a separate backup pool so your data survives anything." },
  { icon: <IconShield />, title: "DDoS protection & firewall", body: "Always-on volumetric mitigation plus managed, firewalled port forwarding on every server." },
  { icon: <IconGauge />, title: "Web console & metrics", body: "Live CPU, memory, disk, and network graphs from the hypervisor, plus a browser console when SSH is down." },
  { icon: <IconApps />, title: "One-click apps", body: "Control panels, databases, and popular apps deploy fully configured on first boot via cloud-init." },
  { icon: <IconScale />, title: "Resize on demand", body: "Scale vCPU, RAM, and disk up as you grow — straight from the dashboard, no rebuild required." },
];

const USE_CASES = [
  { title: "Web & app hosting", body: "Node, PHP, Python, Go — host production sites and APIs with room to grow.", icon: <IconGlobe /> },
  { title: "Game servers", body: "Low-latency Minecraft, Valheim, and more with dedicated resources you control.", icon: <IconServer /> },
  { title: "Docker & self-hosting", body: "Run your own stack — Nextcloud, n8n, databases, and container fleets.", icon: <IconApps /> },
  { title: "Dev & staging", body: "Spin up clean environments in seconds, wipe and redeploy any OS on demand.", icon: <IconTerminal /> },
];

const FAQ = [
  { q: "How fast is provisioning?", a: "Servers are automated end-to-end and typically deploy in under 60 seconds — NVMe clone, cloud-init, IP allocation, and firewall rules all applied automatically." },
  { q: "Do I get full root access?", a: "Yes. Every VPS gives you complete root over SSH with a dedicated IPv4. Install anything, tune the kernel, and run whatever you like." },
  { q: "Can I resize later?", a: "Absolutely. Bump vCPU, RAM, and disk from the dashboard as your workload grows — no need to rebuild from scratch." },
  { q: "Which operating systems can I run?", a: "Ubuntu, Debian, AlmaLinux, Rocky Linux and more, plus control panels and one-click apps that deploy fully configured on first boot." },
  { q: "How does billing work?", a: "Prepaid from a wallet balance in your account. Top up, servers auto-renew monthly, and you can cancel anytime — billing stops at the end of the period." },
];

const COMPARISON = ["Full root access", "NVMe SSD storage", "Dedicated IPv4", "DDoS protection", "Automatic backups", "One-click reinstall", "Real-time metrics"];

function money(cents: number) {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
}

export default async function VpsPage() {
  const [plans, templates] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    db.osTemplate.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
  ]);

  const byCat = (cat: string) => {
    const live = templates
      .filter((t) => t.category === cat)
      .map((t) => (t.version ? `${t.name} ${t.version}`.trim() : t.name));
    return live.length ? live : FALLBACK[cat];
  };
  const groups: CatalogGroup[] = (["PLAIN_OS", "CONTROL_PANEL", "APPLICATION"] as const).map((cat) => ({
    key: cat,
    label: CATEGORY_LABELS[cat],
    items: byCat(cat),
  }));
  const totalImages = groups.reduce((n, g) => n + g.items.length, 0);

  return (
    <>
      {/* Hero */}
      <section className="relative overflow-hidden">
        <div
          className="pointer-events-none absolute inset-x-0 top-0 h-[520px] opacity-80"
          style={{
            backgroundImage:
              "radial-gradient(ellipse 55% 55% at 22% 0%, rgba(59,130,246,0.16), transparent), radial-gradient(ellipse 50% 55% at 82% 8%, rgba(138,112,251,0.17), transparent)",
          }}
        />
        <div className="relative mx-auto max-w-4xl px-5 py-20 text-center sm:px-6 lg:py-28">
          <Reveal>
            <p className="section-label mb-3">VPS Hosting</p>
            <h1 className="text-[2.6rem] font-extrabold leading-[1.05] tracking-tight sm:text-6xl">
              Cloud VPS that feels <span className="grad-text">instant</span>
            </h1>
            <p className="mx-auto mt-6 max-w-2xl text-lg leading-relaxed text-slate-400">
              High-performance virtual servers on enterprise NVMe, with full root access, snapshots,
              backups, and {totalImages}+ one-click images — deployed in under a minute.
            </p>
          </Reveal>
          <Reveal delay={120}>
            <div className="mt-9 flex flex-wrap items-center justify-center gap-3">
              <Link href="/register" className="btn-primary px-6 py-3 text-base">
                Deploy your VPS
                <IconArrow size={16} />
              </Link>
              <Link href="#pricing" className="btn-secondary px-6 py-3 text-base">
                View pricing
              </Link>
            </div>
          </Reveal>
        </div>
      </section>

      {/* Stats */}
      <section className="border-y border-white/[0.06] bg-navy-950/40">
        <div className="mx-auto grid max-w-6xl gap-8 px-5 py-14 sm:grid-cols-2 sm:px-6 lg:grid-cols-4">
          <StatCounter value={47} suffix="s" label="Median deploy time" />
          <StatCounter value={99.9} decimals={1} suffix="%" label="Uptime SLA" />
          <StatCounter value={totalImages} suffix="+" label="One-click images" />
          <StatCounter value={100} suffix="%" label="Root access" />
        </div>
      </section>

      {/* What's included */}
      <section className="mx-auto max-w-6xl px-5 py-20 sm:px-6">
        <SectionHeading label="What's included" title="Everything, on every plan" sub="No feature gates. The smallest box gets the same platform as the largest — you only choose how much horsepower you need." />
        <div className="mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">
          {INCLUDED.map((f, i) => (
            <FeatureCard key={f.title} icon={f.icon} title={f.title} delay={(i % 4) * 60}>
              {f.body}
            </FeatureCard>
          ))}
        </div>
      </section>

      {/* Deploy catalog */}
      <section className="mx-auto max-w-6xl px-5 pb-20 sm:px-6">
        <SectionHeading label="Deploy anything" title="Your stack, ready on first boot" sub={`Pick from ${totalImages}+ images across operating systems, control panels, and one-click apps.`} />
        <Reveal className="mt-12">
          <DeployCatalog groups={groups} />
        </Reveal>
      </section>

      {/* Pricing */}
      <section id="pricing" className="mx-auto max-w-6xl px-5 py-20 sm:px-6">
        <SectionHeading label="Pricing" title="Pick the box that fits" sub="Each plan shows what it is great for, generated from its specs — so you can self-select with confidence." />
        <Reveal className="mt-12">
          <PricingGrid plans={plans} />
        </Reveal>
      </section>

      {/* Comparison */}
      {plans.length > 0 && (
        <section className="mx-auto max-w-6xl px-5 pb-20 sm:px-6">
          <SectionHeading label="Compare" title="What's included" />
          <Reveal className="mt-10">
            <div className="card overflow-x-auto p-0">
              <table className="table-shell min-w-[640px]">
                <thead>
                  <tr>
                    <th>Feature</th>
                    {plans.map((p) => (
                      <th key={p.id} className="text-center">
                        {p.name}
                        <div className="mt-1 text-sm font-bold text-white">{money(p.priceCents)}/mo</div>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td className="font-medium text-slate-300">vCPU</td>
                    {plans.map((p) => (<td key={p.id} className="text-center text-slate-300">{p.cpuCores}</td>))}
                  </tr>
                  <tr>
                    <td className="font-medium text-slate-300">RAM</td>
                    {plans.map((p) => (<td key={p.id} className="text-center text-slate-300">{(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB</td>))}
                  </tr>
                  <tr>
                    <td className="font-medium text-slate-300">Storage</td>
                    {plans.map((p) => (<td key={p.id} className="text-center text-slate-300">{p.diskGB} GB</td>))}
                  </tr>
                  <tr>
                    <td className="font-medium text-slate-300">Bandwidth</td>
                    {plans.map((p) => (<td key={p.id} className="text-center text-slate-300">{p.bandwidthTB} TB</td>))}
                  </tr>
                  {COMPARISON.map((feat) => (
                    <tr key={feat}>
                      <td className="font-medium text-slate-300">{feat}</td>
                      {plans.map((p) => (
                        <td key={p.id} className="text-center">
                          <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
                            <IconCheck size={13} />
                          </span>
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </Reveal>
        </section>
      )}

      {/* Use cases */}
      <section className="mx-auto max-w-6xl px-5 pb-20 sm:px-6">
        <SectionHeading label="Use cases" title="Built for what you build" />
        <div className="mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">
          {USE_CASES.map((u, i) => (
            <FeatureCard key={u.title} icon={u.icon} title={u.title} delay={(i % 4) * 60}>
              {u.body}
            </FeatureCard>
          ))}
        </div>
      </section>

      {/* FAQ */}
      <section className="mx-auto max-w-3xl px-5 pb-20 sm:px-6">
        <SectionHeading label="FAQ" title="Questions, answered" />
        <div className="mt-10 space-y-4">
          {FAQ.map((f, i) => (
            <Reveal key={f.q} delay={i * 40}>
              <div className="card">
                <h3 className="text-base font-semibold text-white">{f.q}</h3>
                <p className="mt-2 text-sm leading-relaxed text-slate-400">{f.a}</p>
              </div>
            </Reveal>
          ))}
        </div>
      </section>

      <section className="mx-auto max-w-6xl px-5 pb-24 sm:px-6">
        <CtaBand />
      </section>
    </>
  );
}

import Link from "next/link";
import { Reveal } from "./Reveal";
import { IconArrow, IconCheck } from "./icons";

/** Curated game titles available as one-click server images in the catalog. */
const TITLES: { name: string; tag: string; grad: string; abbr: string }[] = [
  { name: "Minecraft", tag: "Java & Bedrock", grad: "from-[#4b8b3b] to-[#8bc34a]", abbr: "MC" },
  { name: "Valheim", tag: "Dedicated world", grad: "from-[#3b82f6] to-[#22d3ee]", abbr: "VH" },
  { name: "Rust", tag: "High player counts", grad: "from-[#b7410e] to-[#e6733b]", abbr: "RU" },
  { name: "Palworld", tag: "Co-op survival", grad: "from-[#8a70fb] to-[#6f47f5]", abbr: "PW" },
  { name: "CS2", tag: "Competitive FPS", grad: "from-[#f59e0b] to-[#f97316]", abbr: "CS" },
